        keys(value,Set.of("taskId","runId","epoch","resultRevision","taskStatus","runStatus","runEndedAt","goal","summary","summaryAttribution","outcome","ownerVerificationSequenceObserved","operations","totalOperations","operationsComplete","appVersions","appVersionCoverage","constraintsCoverage","completeOriginalTrace","executionAuthorized"));
        if(!event.optString("taskId").matches(UUID)||!event.optString("runId").matches(UUID)||!event.getString("taskId").equals(value.optString("taskId"))||!event.getString("runId").equals(value.optString("runId"))||integer(event,"epoch",1)!=integer(value,"epoch",1)||!Boolean.FALSE.equals(value.opt("executionAuthorized"))||!Boolean.FALSE.equals(value.opt("completeOriginalTrace"))||!SETTLED.contains(value.optString("taskStatus"))||!SETTLED.contains(value.optString("runStatus")))throw new SecurityException("原任务经过身份或边界已变化");
