        if(!"task_host_or_assistant_report_not_independent_evidence".equals(value.optString("summaryAttribution"))||!"not_separately_recorded; infer_only_as_reviewable_summary".equals(value.optString("constraintsCoverage")))throw new SecurityException("经过摘要不能伪装原始约束或独立证据");
        JSONObject outcome=value.getJSONObject("outcome");keys(outcome,Set.of("classification","basis","businessIndependentlyVerified","toolReceiptIsBusinessSuccess","verificationSeq","resultReviewDigest"));if(!Boolean.FALSE.equals(outcome.opt("businessIndependentlyVerified"))||!Boolean.FALSE.equals(outcome.opt("toolReceiptIsBusinessSuccess")))throw new SecurityException("经过不能提升为业务验证");
