        text.append("\n原任务/执行：").append(original.getString("taskId")).append('/').append(original.getString("runId")).append("\n原结束状态：").append(original.getString("taskStatus")).append("\n结果分类（原生固定）：").append(original.getJSONObject("outcome").getString("classification"))
                .append("\n约束归纳（待审）：").append(constraints).append("\n关键步骤描述（待审，附实际原操作）：\n").append(steps.length()==0?"未选取可核对步骤。\n":steps).append("结果/失败解释（待审）：").append(explanation).append("\n经验（待审）：").append(lesson)
                .append("\n证据覆盖：").append(actual.length()).append('/').append(original.getLong("totalOperations")).append("个操作元数据；不是完整逐字历史。\n适用版本：");
